fn two_sum(nums: &Vec<u32>, target: u32) -> (usize, usize) {
    let n = nums.len();
    // Since every pair‐sum < 256, all values must lie in 0..=255
    let mut buckets: Vec<Vec<usize>> = vec![Vec::new(); 256];
    for (i, &v) in nums.iter().enumerate() {
        let vi = v as usize;
        buckets[vi].push(i);
    }

    for p in 0..n {
        let v = nums[p];
        // if v > target then v + anything >= v > target, so no need to search
        if v > target {
            continue;
        }
        let need = (target - v) as usize;
        // guard, though it should never exceed 255 under the problem assumptions
        if need >= 256 {
            continue;
        }
        let list = &buckets[need];
        // find the smallest index >= p+1 via binary_search’s Err insertion point
        let idx = list.binary_search(&(p + 1)).unwrap_or_else(|x| x);
        if idx < list.len() {
            let q = list[idx];
            // q must be strictly greater than p
            if q > p {
                return (p, q);
            }
        }
    }

    // Problem guarantees there is always a solution
    unreachable!("there must be at least one valid two-sum pair");
}

